     or (select count(*) from app_private.combat_content_publications) <> 294
     or (select count(*) from app_private.combat_content_publications where content_kind='resonance') <> 136
     or (select count(*) from app_private.combat_content_versions) <> 1110
     or exists(select 1 from app_private.combat_content_drafts)
     or (public.read_combat_effect_timing_policy_v1()->>'version')::int <> 8
  then raise exception 'RESONANCE_READINESS_INVENTORY_CHANGED'; end if;
  if (select count(*) from app_private.master_panel_role_assignments where role='game-owner' and enabled) <> 1 then raise exception 'RESONANCE_READINESS_OWNER_INVALID'; end if;
  select user_id into actor from app_private.master_panel_role_assignments where role='game-owner' and enabled limit 1;
  perform app_private.assert_game_owner_v1(actor);
  select jsonb_agg(to_jsonb(v) order by v.id) into history_before
    from app_private.combat_content_versions v;
  select jsonb_agg(to_jsonb(p) order by p.content_key) into untouched_before
    from app_private.combat_content_publications p
    where not exists(select 1 from jsonb_array_elements(rows) x where x->>'id'=p.content_key);
  -- Exact preflight of every current full definition and highest version, before any mutation.
  for item in select value from jsonb_array_elements(rows) loop
    if item->'before'->>'id' is distinct from item->>'id' or item->'after'->>'id' is distinct from item->>'id'
       or (item->'after'->>'contentVersion')::int <> (item->>'version')::int + 1
       or item#>>'{after,ability,behaviors,0,automaticTrigger}' is distinct from 'requirements-met'
    then raise exception 'RESONANCE_READINESS_INVALID_DESIGN: %',item->>'id'; end if;
    select v.definition,v.content_version into current_definition,current_version
       from app_private.combat_content_publications p
       join app_private.combat_content_versions v on v.id=p.version_id
       where p.content_key=item->>'id' and p.content_kind='resonance';
    select coalesce(max(v.content_version),0) into top_version
       from app_private.combat_content_versions v where v.content_key=item->>'id';
    if current_definition is distinct from item->'before'
       or current_version is distinct from (item->>'version')::int
       or top_version is distinct from current_version
    then raise exception 'RESONANCE_READINESS_SOURCE_CHANGED: %',item->>'id'; end if;
  end loop;
  for item in select value from jsonb_array_elements(rows) loop
    select * into receipt from app_private.publish_combat_content_with_floor_v1(
      actor,item->>'id','resonance',item->'after',(item->>'version')::int,(item->>'version')::int
    );
    if receipt.definition is distinct from item->'after'
       or receipt.content_version is distinct from (item->>'version')::int+1
    then raise exception 'RESONANCE_READINESS_WRITE_MISMATCH: %',item->>'id'; end if;
  end loop;
  if (select count(*) from app_private.combat_content_versions) <> 1240
     or (select count(*) from app_private.combat_content_publications) <> 294
     or exists(select 1 from app_private.combat_content_drafts)
     or (public.read_combat_effect_timing_policy_v1()->>'version')::int <> 8
     or exists (
       select 1 from jsonb_array_elements(history_before) prior
       left join app_private.combat_content_versions v on v.id::text=prior->>'id'
       where to_jsonb(v) is distinct from prior
     )
     or untouched_before is distinct from (
       select jsonb_agg(to_jsonb(p) order by p.content_key)
       from app_private.combat_content_publications p
       where not exists(select 1 from jsonb_array_elements(rows) x where x->>'id'=p.content_key)
     )
     or exists (
       select 1 from jsonb_array_elements(rows) as source
       left join app_private.combat_content_publications p on p.content_key=source->>'id'
       left join app_private.combat_content_versions v on v.id=p.version_id
       where v.definition is distinct from source->'after'
     )
  then raise exception 'RESONANCE_READINESS_POSTCHECK_FAILED'; end if;
end
$trigger_release$;
commit;
